create extension if not exists pgcrypto;
create type public.user_role as enum ('admin','analyst','viewer');
create type public.import_status as enum ('pending','processing','completed','failed','cancelled','replaced');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, role public.user_role not null default 'viewer', display_name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.clients (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.equipment (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id), terminal_code text not null, is_active boolean not null default true, first_seen_period date not null, last_seen_period date not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(client_id,terminal_code));
create table public.report_imports (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id), report_name text not null, reference text, period date not null check(period=date_trunc('month',period)::date), generated_date date, entity_code text, provider text, classification text, original_filename text not null, file_hash text not null, storage_path text, status public.import_status not null default 'pending', total_rows integer not null default 0 check(total_rows>=0), valid_rows integer not null default 0 check(valid_rows>=0), invalid_rows integer not null default 0 check(invalid_rows>=0), imported_by uuid not null references auth.users(id), imported_at timestamptz, error_summary jsonb, replaced_import_id uuid references public.report_imports(id), created_at timestamptz not null default now(), unique(client_id,period,report_name,file_hash));
create table public.equipment_monthly_metrics (id uuid primary key default gen_random_uuid(), report_import_id uuid not null references public.report_imports(id), client_id uuid not null references public.clients(id), equipment_id uuid not null references public.equipment(id), period date not null, transaction_count bigint not null, transaction_amount numeric(20,2) not null, active_transaction_days smallint not null, replenishment_count integer not null, replenishment_amount numeric(20,2) not null, dispensed_amount numeric(20,2) not null, collected_amount numeric(20,2) not null, cash_shortage_downtime numeric(7,6) not null check(cash_shortage_downtime between 0 and 1), created_at timestamptz not null default now(), unique(client_id,equipment_id,period));
create table public.import_row_errors (id uuid primary key default gen_random_uuid(), report_import_id uuid not null references public.report_imports(id) on delete cascade, row_number integer not null check(row_number>0), terminal_code text, field_name text, raw_value text, error_code text not null, error_message text not null, created_at timestamptz not null default now());
create table public.import_audit_log (id uuid primary key default gen_random_uuid(), report_import_id uuid not null references public.report_imports(id), action text not null check(action in ('created','completed','failed','cancelled','replaced','corrected')), actor_id uuid not null references auth.users(id), details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index equipment_client_period_idx on public.equipment(client_id,last_seen_period); create index metrics_client_period_idx on public.equipment_monthly_metrics(client_id,period); create index imports_client_period_idx on public.report_imports(client_id,period); create index errors_import_idx on public.import_row_errors(report_import_id);
alter table public.profiles enable row level security; alter table public.clients enable row level security; alter table public.equipment enable row level security; alter table public.report_imports enable row level security; alter table public.equipment_monthly_metrics enable row level security; alter table public.import_row_errors enable row level security; alter table public.import_audit_log enable row level security;
create policy "users read own profile" on public.profiles for select to authenticated using ((select auth.uid())=id);
create policy "admins update profiles" on public.profiles for update to authenticated using ((select auth.jwt()->'app_metadata'->>'role')='admin') with check ((select auth.jwt()->'app_metadata'->>'role')='admin');
create policy "authenticated read clients" on public.clients for select to authenticated using ((select auth.uid()) is not null); create policy "authenticated read equipment" on public.equipment for select to authenticated using ((select auth.uid()) is not null); create policy "authenticated read imports" on public.report_imports for select to authenticated using ((select auth.uid()) is not null); create policy "authenticated read metrics" on public.equipment_monthly_metrics for select to authenticated using ((select auth.uid()) is not null); create policy "authenticated read errors" on public.import_row_errors for select to authenticated using ((select auth.uid()) is not null); create policy "authenticated read audit" on public.import_audit_log for select to authenticated using ((select auth.uid()) is not null);
create policy "operators create imports" on public.report_imports for insert to authenticated with check ((select auth.uid())=imported_by and (select auth.jwt()->'app_metadata'->>'role') in ('admin','analyst')); create policy "operators insert equipment" on public.equipment for insert to authenticated with check ((select auth.jwt()->'app_metadata'->>'role') in ('admin','analyst')); create policy "operators insert metrics" on public.equipment_monthly_metrics for insert to authenticated with check ((select auth.jwt()->'app_metadata'->>'role') in ('admin','analyst')); create policy "operators insert errors" on public.import_row_errors for insert to authenticated with check ((select auth.jwt()->'app_metadata'->>'role') in ('admin','analyst')); create policy "operators insert audit" on public.import_audit_log for insert to authenticated with check ((select auth.uid())=actor_id and (select auth.jwt()->'app_metadata'->>'role') in ('admin','analyst'));
grant select on public.profiles,public.clients,public.equipment,public.report_imports,public.equipment_monthly_metrics,public.import_row_errors,public.import_audit_log to authenticated; grant insert on public.equipment,public.report_imports,public.equipment_monthly_metrics,public.import_row_errors,public.import_audit_log to authenticated;
insert into public.clients(code,name) values ('BCI','BCI'),('BKEVE','BKEVE');
